use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::String(s) = input {
        let hex_string = s.to_string();
        let bytes = hex_string.chars()
            .map(|c| c.to_digit(16).unwrap())
            .collect();
        Value::Array(bytes.into_iter().map(|b| Value::Number(serde_json::Number::from(b as i64))).collect())
    } else {
        Value::Null
    }
}
